{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C196", "C217", "C221", "C265", "C259", "C224", "C256", "C247", "C264", "C239"],
  "contradictory_card_ids": ["C01", "C04", "C17", "C21"],
  "prediction_basis_card_ids": ["C196", "C217", "C221", "C265", "C259", "C224", "C256", "C247", "C264"],
  "claims": [
    {
      "claim": "L6 loperamide records show meaningful hepatic first-pass metabolism: HLM intrinsic clearance 44.3/44.27 µL/min/mg, metabolic t1/2 15.5-18.7 min, human hepatocyte CLint ~13 µL/min/mg, and CYP3A4-mediated N-demethylation. The query shares loperamide's tertiary diphenylacetamide and basic amino-alcohol scaffold, so this supports presystemic hepatic loss.",
      "card_ids": ["C265", "C259", "C224", "C256", "C247", "C264", "C239"]
    },
    {
      "claim": "L5 loperamide efflux records show strong P-gp-mediated gut-wall efflux: pH-gradient ER 18.42 and verapamil-sensitive A→B increase to 45.4 vs B→A 18.7 ×10^-6 cm/s. Combined with L6 hepatic metabolism, this coherently supports F < 20%.",
      "card_ids": ["C196", "C217", "C221"]
    },
    {
      "claim": "L1 high-F records for diphenhydramine, trimipramine, dapoxetine, and milnacipran are less structurally relevant because they lack the tertiary diphenylacetamide and are not accompanied by efflux/first-pass metabolism evidence; they do not outweigh the loperamide-based mechanistic evidence.",
      "card_ids": ["C04", "C17", "C01", "C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "strengthened",
      "card_ids": ["C265", "C259", "C224", "C256", "C247", "C264", "C239"]
    }
  ],
  "evidence_gaps": [
    "No direct oral F measurement for the query in any level.",
    "Loperamide transfer is structural analogy; no query-specific HLM/hepatocyte or efflux data.",
    "L6 values are in vitro intrinsic clearance/t1/2, not scaled in vivo hepatic extraction; units vary across records.",
    "Solubility/dissolution for the low neutral fraction 0.28 is unmeasured.",
    "No query-specific human PK or formulation data."
  ],
  "decision_summary": "Keep low and strengthen. L6 loperamide hepatic-clearance records add coherent first-pass metabolism evidence to the L5 gut-wall efflux evidence for the loperamide-like scaffold, supporting F < 20%. Confidence remains moderate because no direct query PK exists and transfer is structural analogy."
}

